Rules.InvariantScript:
//ClearCollect(noduplicateselection,Filter(varSequence,Value<>99 && Value<>88));
If(
    CountRows(playerSelection) < 3,
    If(
        ThisItem.Value = 99 || ThisItem.Value = 88, //check applied so that user doesnt select already selected cell on grid
        Notify("Please make a different selection as the cell is already taken",NotificationType.Warning),    
        UpdateContext({playerTurnCounter:playerTurnCounter+1});Collect(playerSelection,ThisItem.Value);Update(varSequence,ThisItem,{Value: 99})
    ),
    Notify(
        "You cannot select any more cells. Let COM play his/her turn.",
        NotificationType.Information,
        1000
    )
)

ControlPropertyState.AutoRuleBindingString:
If(
    CountRows(playerSelection) < 3,
    Collect(
        playerSelection,
        ThisItem.Value
    );
    Update(
        varSequence,
        ThisItem,
        {Value: 99}
    ),//if Condition is YES
    If(
        CountRows(playerSelection) = 3,
        Notify(//if Condition is NO
            "You cannot select any more cells. Let COM play his/her turn.",
            NotificationType.Information,
            1000
        )
    )
)

Rules.InvariantScript:
UpdateContext({randomNumber: RandBetween(1,9)});
If(
    randomNumber in remainingPlaces,
    UpdateContext({comturncounter:comturncounter+1});
    Collect(comRandomNumbers,randomNumber);
    Update(varSequence,{Value: randomNumber},{Value: 88});
    Set(varTimerStart,false),
    Notify("Computer is taking time to decide....ZZZZZZZZ",NotificationType.Information,1000)
);
If(Count(comRandomNumbers) = 3,Select(btn_result))

