Rules.InvariantScript:
If(
    Value(Concat(Sort(playerSelection,ThisRecord.Value,SortOrder.Ascending),ThisRecord.Value,"")) in winningCord,
    Notify("User won",NotificationType.Success),
    If(
        Value(Concat(Sort(comRandomNumbers,ThisRecord.Value,SortOrder.Ascending),"")) in winningCord,
    Notify("COM Won the game",NotificationType.Information),Notify("Draw",NotificationType.Information)
    )
);
